import numpy as np
def equation(t, P, params):
    w,k,a,b,c,d,e,f,g,q = params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9]
    s=np.sin(w*t); co=np.cos(w*t); E=np.exp(-k*t)
    return a + b*t + c*t**2 + d*np.sqrt(P) + e*P*s + E*(f*s + g*co)
